const input = $json.body ?? $json;
const requestId = String(input.requestId ?? input.id ?? `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
const product = input.product ?? {};
const images = Array.isArray(product.images) ? product.images : [];
const primaryImage = images[0] ?? '';
const dataUrlMatch = primaryImage.match(/^data:([^;]+);base64,(.+)$/s);
const state = $getWorkflowStaticData('global');
state.jobs ??= {};
state.jobs[requestId] = {
  status: 'processing',
  createdAt: new Date().toISOString(),
};
const item = {
  json: {
    ...input,
    ticket_id: requestId,
    status: 'processing',
    primaryImage,
  },
};
if (dataUrlMatch) {
  item.binary = {
    reference: {
      data: dataUrlMatch[2],
      mimeType: dataUrlMatch[1],
      fileName: 'reference-image',
    },
  };
}
return [item];

const primaryImage = String($json.primaryImage ?? '');
const match = primaryImage.match(/^data:([^;]+);base64,(.+)$/s);
if (!match) {
  throw new Error('La imagen de referencia no tiene un formato data URL válido.');
}
return [{
  json: $json,
  binary: {
    reference: {
      data: match[2],
      mimeType: match[1],
      fileName: 'reference-image',
    },
  },
}];

