    body ? '2. SUBTITLE / BENEFIT TEXT: "' + body + '" in clean, highly readable typography.' : '',
    price ? '3. HIGHLIGHTED PRICE BADGE: A prominent, stylish modern graphical badge or sticker displaying "' + price + '".' : '',
    validity ? '4. PROMOTION VALIDITY: "Válido: ' + validity + '".' : '',
